CREATE TABLE reading_work (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,resource_id UUID NOT NULL,kind VARCHAR(24) NOT NULL,original_language VARCHAR(32),serialization_status VARCHAR(32),version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(resource_id) REFERENCES resource(id),UNIQUE(owner_id,resource_id));
CREATE TABLE reading_edition (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,work_id UUID NOT NULL,name VARCHAR(512) NOT NULL,language VARCHAR(32),publisher VARCHAR(256),source VARCHAR(256),preference_weight INTEGER NOT NULL DEFAULT 0,availability VARCHAR(32) NOT NULL DEFAULT 'AVAILABLE',version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(work_id) REFERENCES reading_work(id));
CREATE TABLE reading_volume (id UUID PRIMARY KEY DEFAULT uuid_v7(),edition_id UUID NOT NULL,kind VARCHAR(16) NOT NULL,display_label VARCHAR(256),structured_number VARCHAR(64),sort_order INTEGER NOT NULL,title VARCHAR(512),cover_attachment_id UUID,FOREIGN KEY(edition_id) REFERENCES reading_edition(id),FOREIGN KEY(cover_attachment_id) REFERENCES attachment(id),UNIQUE(edition_id,sort_order));
CREATE TABLE reading_chapter (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,work_id UUID NOT NULL,edition_id UUID NOT NULL,volume_id UUID,resource_id UUID NOT NULL,structured_number VARCHAR(64) NOT NULL,display_label VARCHAR(256),title VARCHAR(512),sort_order INTEGER NOT NULL,content_kind VARCHAR(24) NOT NULL,page_count INTEGER,text_length INTEGER,availability VARCHAR(32) NOT NULL DEFAULT 'AVAILABLE',lifecycle VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',version BIGINT NOT NULL DEFAULT 0,CHECK(sort_order>=0),FOREIGN KEY(work_id) REFERENCES reading_work(id),FOREIGN KEY(edition_id) REFERENCES reading_edition(id),FOREIGN KEY(volume_id) REFERENCES reading_volume(id),FOREIGN KEY(resource_id) REFERENCES resource(id),UNIQUE(edition_id,sort_order));
CREATE TABLE reading_comic_page (id UUID PRIMARY KEY DEFAULT uuid_v7(),chapter_id UUID NOT NULL,attachment_id UUID NOT NULL,page_order INTEGER NOT NULL,page_role VARCHAR(24) NOT NULL DEFAULT 'NORMAL',width INTEGER,height INTEGER,spread_hint VARCHAR(32),CHECK(page_order>=0),FOREIGN KEY(chapter_id) REFERENCES reading_chapter(id) ON DELETE CASCADE,FOREIGN KEY(attachment_id) REFERENCES attachment(id),UNIQUE(chapter_id,page_order));
